INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1533223-ise291', 'stk-posty', 'ISE 291', 'info', '{"desc": "ISE291 Term 211\n\nالكورس توه جديد والكوردنيتر (سيد مجاهد) للحين مو عارف كيف يضبط الكورس لامن متريل ولا من سلايدات ولا حتى اختبارات\n\nالمتريل: كل ترم يضيف ويحذف شباتر من الكورس والدكاترة اغلبهم كانوا متاخرين عن السيلابوس واضطروا يسوون محاضرات اضافية، ومع هذا ماخلصنا الا اول ٩ شباتر و الشابتر العاشر محد وصله\n\nالسلايدات: مدري اذا اصلا تستحق اسميها سلايدات هي عبارة عن ملف جوبيتر وفيه اكواد و كومنتات فقط لاغير وجدا ممله\n\nالاختبارات: اول مره في حياتي اشوف كورس الدكاترة مو عارفين يضبطون وقت الاختبار، لدرجة الفاينل كان عبارة عن ثلاث بارتات وكثير طلاب مالحقوا يوصلون للبارت الثالث بسبب طول الاسئلة وضيق الوقت ماعرف اذا الهدف من الاختبار هو قياس فهمك للمادة ولاسبيد رن لان كل الاختبارات اوبن بوك ف اعتقد بسببها يضيق الوقت بشكل مو طبيعي ونفس السالفة صارت في الميد لاكن في الميد كان اهون شيء بس نفس الفكرة كان اسئلة كثيرة وطويله ووقت قصير ف يصير مايمديك تفكر بس تدور السيل الي تتكلم عن نفس الموضوع وتسوي كوبي بيست للكود\n\nبشكل عام الكورس جدا سيء وغير جاهز ابد نصيحتي للي ناوي ياخذه الترم الجاي يحاول ياجله اذا يمديه", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-291-introduction-to-data-science/184113/4", "user": "Posty", "ts": 1640988847000, "tid": 184113, "pn": 4}}', 1640988847000, 1794754628, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-posty-ise291', 'stk-posty', 'ISE 291', 'doc', '{"docs": [{"id": "stk-dr-f98287", "n": "Dr. Anas Alghazi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ISE 291- 211\n\nالتحضير : كنا في مبنى ٦٠ ف كان متسامح جدا في التاخير لاكن مدري كيف بيصير اذا تحسن الوضع وصار في مبنى قريب من الجبل\nطريقة الشرح : يقرا السلايدات بشكل ممل، واذا حس ان فيه حاجة تحتاج شرح فصلها على السبورة والدكتور فاهم للامانه وغالبا اذا بتركز معاه بتقدر تفهم كلش\nالكويزات : كانت سهله وتصحيحه جدا جميل\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي: A\nالصوت:واضح", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1532697-ise291", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/anas-alghazi/98287/5", "user": "Posty", "ts": 1636488231000, "tid": 98287, "pn": 5}}]}', 1636488231000, 1794754628, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-s.q-ise291', 'stk-s.q', 'ISE 291', 'doc', '{"docs": [{"id": "stk-dr-f98287", "n": "Dr. Anas Alghazi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ANAS ALGHAZI\n\nISE 291- 211\n\nالتحضير : بعد بداية الكلاس ب 10 دقائق يفتح الكشف من BB وينادي على الأسماء ولو تاخرت وكان ماخذ الحضور تروح له نهايه الكلاس ويحضرك.\n\nطريقة الشرح : صراحة هذي السلبية الوحيدة فيه ، شرحه عادي وممل جدا يفتح سلايدات القسم ويقراها وهو قاعد واذا فيه قانون او حاجة تحتاج تفصيل قام وشرح على السبورة ، ممكن اذا ركزت معاه بتفهم ولكن انا اشوف انه صعب جدا التركيز معه بسبب نبرة صوته المنخفضة بعض الشيء والمملة خصوصا انه كلاسنا كان ساعة وربع\n\nالكويزات : اعطانا 4 كويزات وحذف اسوء واحد ، أول كويز كان ورقي والباقي كان على Jupyter Notebook لازم تجيب لابتوب معك وقت الكويز وتحمل ملف الكويز من الBB وتكتب الكود فالجوبتر وترجع تسبمت الملف فالBB ، يسوي ميكب كويز للي ما عنده لابتوب فاليوم الي بعد يوم الكويز في مبنى 22 ، بالنسبة لمستوى الكويزات تافهة جدا وتقريبا نسخ لصق من السلايدات و الهومووركات الي من القسم\n\nالمياجر: ميد تيرم و كان كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: B+\n\nالصوت: ضعيف نوعا ما ونبرة صوته مملة مثل ما ذكرت فوق لازم تقعد قدام عشان تركز\n\nإضافات :\n\n1- الدكتور حبيب جدا ومتعاون مع الطلاب ما عنده مشكلة يأجل الكويز اذا الطلاب ما ناسبهم وقته\n2- الدكتور خيار ممتاز جدا للي بياخذ المادة سلف ستدي وبيعتمد على مقاطع الدكتور مجاهد فاليوتيوب لفهم الكونسبت ( مقاطع الدكتور مجاهد: https://www.youtube.com/playlist?list=PLIBS8ORjf4HQPFtU9EHHvI-aIi_RdcF2b )\n3- المادة تعتبر جديدة وكل ترم يصير فيه تغيير ف ممكن كلامي عن الدكتور انس يكون مختلف عن الواقع في الاترام الجاية", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533344-ise291", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/anas-alghazi/98287/6", "user": "S.Q", "ts": 1641541611000, "tid": 98287, "pn": 6}}]}', 1641541611000, 1794754628, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12192-ise291', 'stk-user12192', 'ISE 291', 'doc', '{"docs": [{"id": "stk-dr-f138943", "n": "Dr. Mojeeb Al-Khiaty", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ISE 291 - TERM 211\n\nالتحضير : يبدأ يأخذ التحضير بعد نهاية المحاضرة بدقيقتين أو ثلاث.\n\nطريقة الشرح : فاهم لكن أحسه ما يقدر يوصل المعلومة للطالب، يمطمط في جزئيات ما تستاهل ويضيع عليها الكلاس. تابعت معه كم أسبوع إلين ما قدرت أتحمل.\n\nالكويزات : 4 ويلغَى أسوء كويز من نظام المادة، متوسطة الصعوبة، أول كويز ورقي الباقي ببايثون تجيب اللابتوب في الكلاس، في نهاية الكلاس 15 دقيقة تقريبا و 1-2 دقيقة للتسليم.\n\nالميد : كومن\n\nالفاينلات : كومن\n\nالصوت: واضح، اللغة تعبانة وذا سبب من أسباب ضعف الشرح\n\nالتقييم النهائي: C\n\nإضافات : الدكتور طيب وحبيب، تنام أو تنشغل بالجوال ما يقول شيء.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533327-ise291", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mojeeb-al-khiaty/138943/13", "user": "user12192", "ts": 1641396472000, "tid": 138943, "pn": 13}}]}', 1641396472000, 1794754628, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11896-ise291', 'stk-user11896', 'ISE 291', 'doc', '{"docs": [{"id": "stk-dr-f173386", "n": "Dr. Syed Mujahid", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ISE 291-T203 (عن بعد)\nالتحضير : إذا حضرت المحاضرة في البلاكبورد تتحضر تلقائيا بس لازم تحضر بدري عشان تنحسب كحاضر\nطريقة الشرح : في البداية يراجع لنا كل اللي درسناه سابقا ثم بعدها يدخل في الدرس الجديد فيعرض لنا السلايدات حقت المادة ويكتب عليها بعض الأشياء وينفذ الكود اللي في السلايدات ويورينا الناتج ويشرح لنا عنه، وأحيانا يعدل على الكود بعدها ينفذه عشان يشرح حاجة معينة. وشرحه ممتاز غالبا والدكتور يتجاوب مع الأسئلة وهذي مقاطع لشرح الدكتور لهذي المادة لمن أراد أن يحكم هل تناسبه طريقة الدكتور أو لا\n\nالكويزات : 5 كويزات وحذف لنا أسوأ واحد (الظاهر جميع دكاترة هذي المادة سوو نفس الحركة) والكويزات كانت متوسطة الصعوبة وأشوف أن الدكتور متساهل في تصحيح الكويزات\nالمياجر: موحدة\nالفاينلات : موحدة\nالقريد النهائي: A\nالصوت: واضح\nإضافات : تعامل الدكتور مع الطلاب جيد. الدكتور هو الكوردينيتور حق المادة وأظنه هو اللي مسوي السلايدات حقت المادة ولأنه هو اللي مسويها فأعتقد أنه أقدر على شرحها من غيره من دكاترة ISE 291 وإن كان معظم اللي درسوها في ترم 203 جيدين حسب ما سمعت من طلابهم.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531425-ise291", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-syed-mujahid/173386/7", "user": "user11896", "ts": 1629754537000, "tid": 173386, "pn": 7}}]}', 1629754537000, 1794754628, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-saleh_h-ise291', 'stk-saleh_h', 'ISE 291', 'doc', '{"docs": [{"id": "stk-dr-f173386", "n": "Dr. Syed Mujahid", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ISE 291 - Term 211\n\nالتحضير : يحضر نهاية المحاضرة وينادي بالاسماء ويمشي التأخير بغض النظر عن الوقت.\nطريقة الشرح : يشرح من النوتات ويشرح لك كيف الكود يشتغل ويعدل عليه عشان يوريك استخدامات ثانية له وشرحه واضح وممتاز.\nالكويزات : متوسطة يجيبها من السلايدات ويعدل على الكود تعديل بسيط.\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A\nالصوت: واضح\nإضافات : الدكتور تعامله محترم مع الطلاب ومتفهم وهو الكوردنيتر للكورس ومسوي السلايدات حقته ولا تتردد تنزل عنده.\n\nوموفقين إن شاء الله…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533444-ise291", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-syed-mujahid/173386/8", "user": "Saleh_H", "ts": 1642083073000, "tid": 173386, "pn": 8}}]}', 1642083073000, 1794754628, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sadguts-ise291', 'stk-sadguts', 'ISE 291', 'doc', '{"docs": [{"id": "stk-dr-f173386", "n": "Dr. Syed Mujahid", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ISE 291 - Term 211\nالتحضير : بالنهاية ولا يهتم للتاخير\nطريقة الشرح : شرحه واضح ورهيب يحلل كل سطر ويشرح وش يسوي واحيانا يوريك استخدامات ثانية للكود واختصارات رهيبة. يغطي كل المواضيع في النوتات ويضيف من عنده واذا مافهمت شيء معاه اساله ويجاوبك ويفصلها لك\nالكويزات : نفس السلايدات واحيانا يحط فقرة فيها تغيير بسيط\nالميد والفاينل: متوسطة لكن فيه كم فقرة صعبة ولازم تفهم الكود والكونسبت صح عشان تجاوبها\nإضافات : الدكتور مجاهد هو الكوردينيتر وفاهم المادة ومجالها صح واخلاقه جدا عالية من الاخير مايتفوت. لو ماقدرت تنزل عنده مقاطعه عاليوتيوب موجودة شرح المادة كاملة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533779-ise291", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-syed-mujahid/173386/9", "user": "SadGuts", "ts": 1645338937000, "tid": 173386, "pn": 9}}]}', 1645338937000, 1794754628, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-me_student91-ise291', 'stk-me_student91', 'ISE 291', 'doc', '{"docs": [{"id": "stk-dr-f173386", "n": "Dr. Syed Mujahid", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ISE 291\nTERM 243\nالتحضير : آخر الكلاس وينادي بالأسماء ومتساهل نوعا ما في التأخير\nطريقة الشرح : يستخدم سلايدات القسم ويحاول يسأل احيانا و يهتم بتعلم الطلاب، شرييح\nالكويزات : اختياري 10 أسئلة كونسبت\nالمياجر: المادة ميد، كومن\nالفاينلات : كومن\nالقريد النهائي: A+\nالصوت: واضح\nإضافات : الدكتور متعاون من ناحية تأجيل الكويزات وواضح جدا في موضوع الاوفيس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1540208-ise291", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-syed-mujahid/173386/10", "user": "ME_STUDENT91", "ts": 1755035088237, "tid": 173386, "pn": 10}}]}', 1755035088237, 1794754628, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
